INSERT OR IGNORE INTO questions
  (id, track_id, topic, difficulty, question_type, prompt, options_json, answer_json, explanation, source_type, source_reference, language)
VALUES
('sg-official-2019s-am-11','exam-sg','メール認証・SPF','standard','single_choice','【平成31年度 春期 午前 問11】SPF（Sender Policy Framework）を利用する目的はどれか。','[{"id":"a","text":"HTTP通信の経路上での中間者攻撃を検知する"},{"id":"b","text":"LANへのPCの不正接続を検知する"},{"id":"c","text":"内部ネットワークへの侵入を検知する"},{"id":"d","text":"メール送信者のドメインのなりすましを検知する"}]','"d"','SPFはDNSに登録された送信元情報を使い，メール送信ドメインのなりすましを検知する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000ddiw-att/2019h31h_sg_am_qs.pdf','ja'),
('sg-official-2019s-am-12','exam-sg','ファイルアクセス権限','standard','single_choice','【平成31年度 春期 午前 問12】ファイルの属性情報として，ファイルに対する読取り，書込み，実行の権限を独立に設定できるOSがある。この3種類の権限は，それぞれに1ビットを使って許可，不許可を設定する。この3ビットを8進数表現0～7の数字で設定するとき，次の試行結果から考えて，適切なものはどれか。試行結果：0では読取り・書込み・実行不可，3では読取りと書込み可で実行不可，7では全て可。','[{"id":"a","text":"2を設定すると，読取りと実行ができる"},{"id":"b","text":"4を設定すると，実行だけができる"},{"id":"c","text":"5を設定すると，書込みだけができる"},{"id":"d","text":"6を設定すると，読取りと書込みができる"}]','"b"','3は2と1のビットで読取りと書込みを表すため，残る4が実行権限。したがって4なら実行だけが可能。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000ddiw-att/2019h31h_sg_am_qs.pdf','ja'),
('sg-official-2019s-am-13','exam-sg','物理的セキュリティ・入退室管理','standard','single_choice','【平成31年度 春期 午前 問13】入室時と退室時にIDカードを用いて認証を行い，入退室を管理する。このとき，入室時の認証に用いられなかったIDカードでの退室を許可しない，又は退室時の認証に用いられなかったIDカードでの再入室を許可しないコントロールを行う仕組みはどれか。','[{"id":"a","text":"TPMOR（Two Person Minimum Occupancy Rule）"},{"id":"b","text":"アンチパスバック"},{"id":"c","text":"インターロックゲート"},{"id":"d","text":"パニックオープン"}]','"b"','アンチパスバックは入退室の記録の整合性を確認し，共連れやカードの使い回しを抑止する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000ddiw-att/2019h31h_sg_am_qs.pdf','ja'),
('sg-official-2019s-am-14','exam-sg','PCI DSS・カードセキュリティコード','standard','single_choice','【平成31年度 春期 午前 問14】PCI DSS v3.2.1において，取引承認を受けた後の加盟店及びサービスプロバイダにおけるカードセキュリティコードの取扱方法の組合せのうち，適切なものはどれか。','[{"id":"a","text":"加盟店では暗号化して保管し，サービスプロバイダでも暗号化して保管する"},{"id":"b","text":"加盟店では平文で保管し，サービスプロバイダでは保管しない"},{"id":"c","text":"加盟店では保管せず，サービスプロバイダでは平文で保管する"},{"id":"d","text":"加盟店でもサービスプロバイダでも保管しない"}]','"d"','PCI DSSでは取引承認後のカードセキュリティコードは，暗号化していても保存してはならない。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000ddiw-att/2019h31h_sg_am_qs.pdf','ja'),
('sg-official-2019s-am-15','exam-sg','侵入防止システム・IPS','standard','single_choice','【平成31年度 春期 午前 問15】IPSの説明はどれか。','[{"id":"a","text":"Webサーバなどの負荷を軽減するために，暗号化や復号の処理を高速に行う専用ハードウェア"},{"id":"b","text":"サーバやネットワークへの侵入を防ぐために，不正な通信を検知して遮断する装置"},{"id":"c","text":"システムの脆弱性を見つけるために，疑似的に攻撃を行い侵入を試みるツール"},{"id":"d","text":"認可されていない者による入室を防ぐために，指紋，虹彩などの生体情報を用いて本人認証を行うシステム"}]','"b"','IPSは不正通信を検知するだけでなく遮断する侵入防止システム。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000ddiw-att/2019h31h_sg_am_qs.pdf','ja'),
('sg-official-2019s-am-16','exam-sg','パスワードリスト攻撃','standard','single_choice','【平成31年度 春期 午前 問16】特定のサービスやシステムから流出した認証情報を攻撃者が用いて，認証情報を複数のサービスやシステムで使い回している利用者のアカウントへのログインを試みる攻撃はどれか。','[{"id":"a","text":"パスワードリスト攻撃"},{"id":"b","text":"ブルートフォース攻撃"},{"id":"c","text":"リバースブルートフォース攻撃"},{"id":"d","text":"レインボー攻撃"}]','"a"','流出したIDとパスワードの組合せを別サービスで試す攻撃がパスワードリスト攻撃。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000ddiw-att/2019h31h_sg_am_qs.pdf','ja'),
('sg-official-2019s-am-17','exam-sg','ネットワーク・IPマスカレード','standard','single_choice','【平成31年度 春期 午前 問17】社内PCからインターネットに通信するとき，パケット中にある社内PCのプライベートIPアドレスとポート番号の組合せを，ファイアウォールのインターネット側のIPアドレスとポート番号の組合せに変換し，社内PCのプライベートIPアドレスを隠蔽できるものはどれか。','[{"id":"a","text":"BGP"},{"id":"b","text":"IPマスカレード"},{"id":"c","text":"OSPF"},{"id":"d","text":"フラグメンテーション"}]','"b"','IPマスカレード（NAPT）はIPアドレスとポート番号を変換し，内部端末のアドレスを外部から直接見えなくする。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000ddiw-att/2019h31h_sg_am_qs.pdf','ja'),
('sg-official-2019s-am-18','exam-sg','セキュリティ評価・ペネトレーションテスト','standard','single_choice','【平成31年度 春期 午前 問18】ペネトレーションテストに該当するものはどれか。','[{"id":"a","text":"実行プログラムの設計書やソースコードを調べ，開発工程のセキュリティ問題を確認する"},{"id":"b","text":"Webサーバのコンテンツファイルのハッシュ値を管理し，定期的に一致を確認する"},{"id":"c","text":"公開Webサーバや組織のネットワークの脆弱性を探索し，サーバに実際に侵入できるか確認する"},{"id":"d","text":"サーバやネットワーク機器のIPFIX情報から，各PCの通信に異常な振る舞いがないか確認する"}]','"c"','ペネトレーションテストは攻撃者の手法で実際の侵入を試み，脆弱性や防御の有効性を評価する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000ddiw-att/2019h31h_sg_am_qs.pdf','ja'),
('sg-official-2019s-am-19','exam-sg','ネットワーク・TCPポート80','standard','single_choice','【平成31年度 春期 午前 問19】PCへの侵入に成功したマルウェアがインターネット上の指令サーバと通信を行う場合に，宛先ポートとして使用されるTCPポート番号80に関する記述のうち，適切なものはどれか。','[{"id":"a","text":"DNSのゾーン転送に使用されることから，通信がファイアウォールで許可されている可能性が高い"},{"id":"b","text":"WebサイトのHTTPS通信での閲覧に使用されることから，マルウェアと指令サーバとの通信が侵入検知システムで検知される可能性が低い"},{"id":"c","text":"Webサイトの閲覧に使用されることから，通信がファイアウォールで許可されている可能性が高い"},{"id":"d","text":"ドメイン名の名前解決に使用されることから，マルウェアと指令サーバとの通信が侵入検知システムで検知される可能性が低い"}]','"c"','TCP 80番ポートはHTTPの標準ポートであり，通常のWeb閲覧のためファイアウォールで許可されていることが多い。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000ddiw-att/2019h31h_sg_am_qs.pdf','ja'),
('sg-official-2019s-am-20','exam-sg','無線LAN・アクセス制御','standard','single_choice','【平成31年度 春期 午前 問20】無線LANを利用できる者を限定したいとき，アクセスポイントへの第三者による無断接続の防止に最も効果があるものはどれか。','[{"id":"a","text":"MACアドレスフィルタリングを設定する"},{"id":"b","text":"SSIDには英数字を含む8字以上の文字列を設定する"},{"id":"c","text":"セキュリティ方式にWEPを使用し，十分に長い事前共有鍵を設定する"},{"id":"d","text":"セキュリティ方式にWPA2-PSKを使用し，十分に長い事前共有鍵を設定する"}]','"d"','十分に長い事前共有鍵を用いたWPA2-PSKは，MACアドレス制限やSSID変更，脆弱なWEPより有効。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000ddiw-att/2019h31h_sg_am_qs.pdf','ja');
